{
  "schemaVersion": "0.2",
  "slug": "login",
  "name": "Login",
  "status": "experimental",
  "purpose": "Email and password sign-in fragment composed from form, input, password-input, and button.",
  "scenarios": [
    "Sign in to a product with email and password",
    "Reveal or hide the password field",
    "Jump to the register scene from the login card"
  ],
  "props": {
    "locale": {
      "type": "string",
      "required": false,
      "description": "BCP 47 locale for bundled block copy.",
      "default": "en"
    },
    "onSubmit": {
      "type": "event",
      "required": false,
      "description": "Called with email, password, and remember after client validation."
    },
    "onRegisterClick": {
      "type": "event",
      "required": false,
      "description": "Called when the create-account action is activated."
    }
  },
  "variants": [
    {
      "name": "density",
      "values": ["comfortable", "compact"],
      "default": "comfortable",
      "description": "Inherits density from token rungs rather than a local viewport query."
    }
  ],
  "states": [
    { "name": "default", "description": "Idle sign-in form." },
    { "name": "invalid", "description": "Client validation failed." }
  ],
  "composition": {
    "allowedParents": ["page", "dialog", "card"],
    "allowedChildren": ["form", "input", "password-input", "button", "checkbox", "card", "typography"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not collect passwords in a plain text input when password-input is available.",
    "Do not claim 21 authored languages; 19 locales are ICU skeletons."
  ],
  "a11y": {
    "role": "form",
    "keyboard": ["Tab moves between fields", "Enter submits the form"],
    "focus": "Fields and actions remain in document order with a visible focus ring.",
    "labeling": "Email, password, remember, and submit have visible labels.",
    "wcag": ["2.1.1", "2.4.7", "3.3.2", "4.1.2"]
  },
  "responsive": {
    "strategy": "Single-column card with max-inline-size; compact viewports keep 44px targets via tokens.",
    "breakpoints": {
      "compact": "Card uses full inline size with 44px targets.",
      "medium": "Card is centered up to 28rem.",
      "large": "Card is centered up to 28rem."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction comes from locale language, never a hardcoded ltr attribute.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "login",
    "states": ["default", "invalid"],
    "intents": ["authenticate"]
  }
}

import { Button, Card, Checkbox, Form, Input, PasswordInput, Typography } from '@chameleon-ui/components-react'
import { useState, type FormEvent } from 'react'
import { createBlockCopy } from '../copy.js'
import { loginLocaleTrees } from './locale-map.js'
import './styles.css'

export interface LoginSubmitValues {
  email: string
  password: string
  remember: boolean
}

export interface LoginProps {
  locale?: string
  onSubmit?: (values: LoginSubmitValues) => void
  onRegisterClick?: () => void
  className?: string
}

function isEmail(value: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
}

export function Login({ locale = 'en', onSubmit, onRegisterClick, className }: LoginProps) {
  const { t } = createBlockCopy(loginLocaleTrees, locale)
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [remember, setRemember] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const classes = ['cu-block-login', className].filter(Boolean).join(' ')

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!email.trim() || !password) {
      setError(t('login.errorRequired'))
      return
    }
    if (!isEmail(email.trim())) {
      setError(t('login.errorInvalid'))
      return
    }
    setError(null)
    onSubmit?.({ email: email.trim(), password, remember })
  }

  return (
    <section
      className={classes}
      data-ai-role="login"
      data-ai-intent="authenticate"
      data-ai-state={error ? 'invalid' : 'default'}
    >
      <Card className="cu-block-login__card" padding="lg" variant="outlined">
        <Typography variant="heading-1">{t('login.title')}</Typography>
        <Typography variant="body">{t('login.subtitle')}</Typography>
        <p className="cu-block-login__meta">{t('login.sessionCount', { count: remember ? 1 : 0 })}</p>
        {error ? (
          <p className="cu-block-login__error" role="alert">
            {error}
          </p>
        ) : null}
        <Form onSubmit={handleSubmit} submitLabel={t('login.submit')}>
          <Input
            autoComplete="email"
            invalid={Boolean(error)}
            label={t('login.emailLabel')}
            onChange={setEmail}
            type="email"
            value={email}
          />
          <PasswordInput
            hideLabel={t('login.hidePassword')}
            invalid={Boolean(error)}
            label={t('login.passwordLabel')}
            onChange={setPassword}
            showLabel={t('login.showPassword')}
            value={password}
          />
          <Checkbox checked={remember} label={t('login.rememberLabel')} onChange={setRemember} />
        </Form>
        <div className="cu-block-login__register">
          <Typography variant="caption">{t('login.registerPrompt')}</Typography>
          <Button onClick={onRegisterClick} type="button" variant="outline">
            {t('login.registerAction')}
          </Button>
        </div>
      </Card>
    </section>
  )
}

{
  "slug": "login",
  "type": "registry:block",
  "name": "Login",
  "dependencies": ["button", "card", "checkbox", "form", "input", "password-input", "typography"],
  "theme": { "constraints": [] },
  "rtl": true,
  "platforms": {
    "compact": true,
    "medium": true,
    "large": true
  },
  "preview": {
    "width": 390,
    "title": "Email and password sign-in"
  }
}

.cu-block-login {
  display: grid;
  justify-items: center;
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
}

.cu-block-login__card {
  display: grid;
  gap: var(--cu-space-3);
  inline-size: min(100%, 28rem);
}

.cu-block-login__meta,
.cu-block-login__error {
  margin-block: 0;
  color: var(--cu-color-fg-default);
  font-size: var(--cu-typography-size-caption);
}

.cu-block-login__error {
  color: var(--cu-color-palette-brand);
}

.cu-block-login__register {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--cu-space-2);
}
